class RateLimiter:
    def __init__(self, max_calls: int, period_seconds: float):
        if max_calls <= 0 or period_seconds <= 0:
            return None
        self.max_calls = max_calls
        self.period_seconds = period_seconds
        self.timestamps = []

    def allow(self, timestamp: float) -> bool:
        self.timestamps.append(timestamp)
        # Remove timestamps that are outside the sliding window
        while self.timestamps and self.timestamps[0] < timestamp - self.period_seconds:
            self.timestamps.pop(0)
        # Check if the number of calls in the window exceeds the limit
        return len(self.timestamps) <= self.max_calls

