class Logger:
    def __init__(self):
        self.messages = {}

    def should_print(self, message: str, timestamp: int) -> bool:
        if message not in self.messages:
            self.messages[message] = timestamp
            return True
        else:
            if timestamp - self.messages[message] >= 10:
                self.messages[message] = timestamp
                return True
            else:
                return False

class HitCounter:
    def __init__(self):
        # Initialize an empty list to store hit timestamps
        self.hits = []

    def hit(self, timestamp: int) -> None:
        # Append the current timestamp to the hits list
        self.hits.append(timestamp)

    def get_hits(self, timestamp: int) -> int:
        # If the hits list is empty, return 0
        if not self.hits:
            return 0

        # Find the index of the first timestamp that is within the last 300 seconds
        left = 0
        right = len(self.hits) - 1
        while left <= right:
            mid = (left + right) // 2
            if self.hits[mid] <= timestamp - 300:
                left = mid + 1
            else:
                right = mid - 1

        # The number of valid hits is the total hits minus the number of hits outside the last 300 seconds
        return len(self.hits) - left

def safe_add(a: int, b: int) -> int:
    INT_MIN = -2**31
    INT_MAX = 2**31 - 1

    result = a + b

    if result < INT_MIN:
        return INT_MIN
    elif result > INT_MAX:
        return INT_MAX
    else:
        return result

def flatten(lst: list) -> list:
    result = []

    def helper(sub_lst):
        for item in sub_lst:
            if isinstance(item, list):
                helper(item)
            else:
                result.append(item)

    helper(lst)
    return result

def deep_get(d: dict, keys: list, default=None):
    if not keys:
        return d
    current = d
    for key in keys:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return default
    return current

class CircularBuffer:
    def __init__(self, size: int):
        if size <= 0:
            return None
        self.size = size
        self.buffer = [None] * size
        self.head = 0
        self.tail = 0
        self.count = 0

    def write(self, item) -> None:
        if self.is_full():
            self.head = (self.head + 1) % self.size
        else:
            self.count += 1
        self.buffer[self.tail] = item
        self.tail = (self.tail + 1) % self.size

    def read(self):
        if self.count == 0:
            return None
        item = self.buffer[self.head]
        self.head = (self.head + 1) % self.size
        self.count -= 1
        return item

    def is_full(self) -> bool:
        return self.count == self.size

def my_pow(x: float, n: int) -> float:
    if n == 0:
        return 1.0
    if x == 0:
        return 0.0
    if n < 0:
        x = 1 / x
        n = -n

    result = 1.0
    while n > 0:
        if n % 2 == 1:
            result *= x
        x *= x
        n //= 2

    return result
